def find_atg_orfs(s, minaa=60):
    res=[]
    for frame in range(3):
        p=frame
        seg=[]
        # collect stop-free windows
        startpos=None
        for pos in range(frame, len(s)-2, 3):
            aa=table[s[pos:pos+3]]
            if aa=='*':
                startpos=None
            else:
                if startpos is None:
                    startpos=pos
                if s[pos:pos+3]=='ATG' and (pos==startpos):
                    pass
        # simpler: for each ATG, extend until stop
    for pos in range(len(s)-2):
        if s[pos:pos+3]=='ATG':
            j=pos
            prot=''
            while j+3<=len(s):
                aa=table[s[j:j+3]]
